using System.Reflection.Metadata;
using System.Reflection.Metadata.Ecma335;
using System.Reflection.PortableExecutable;
using Seamless.Management;
using Seamless.Management.Server;

namespace Management.Tests;

public sealed class QueryAuditMetadata{
    private static CompiledSource Compile(string body,string parameters="int[] values,int threshold=987654321")=>new RuntimeCompiler().Compile(new("1",[new("Query.cs","using System.Linq;namespace AuditSample;public static class Queries{static Queries(){throw new System.InvalidOperationException(\"DO_NOT_EXECUTE\");}public static int Run("+parameters+"){"+body+"}}")],[]),entryType:"AuditSample.Queries",entryMember:"Run");
    [Fact]public void EntryIdentityUsesOriginalMethodWithoutRunningTheAssembly(){
        var compiled=Compile("return values.Where(value=>value>threshold).Sum();");Assert.NotEmpty(compiled.AssemblyBytes);var metadata=Assert.IsType<Seamless.Management.Server.QueryAuditMetadata>(compiled.AuditMetadata);Assert.Equal("AuditSample",metadata.Namespace);Assert.Equal("Queries",metadata.TypeName);Assert.Equal("Run",metadata.MethodName);Assert.Contains("threshold",metadata.MethodSignature!);Assert.DoesNotContain("987654321",metadata.MethodSignature!);Assert.Equal(compiled.Result.ArtifactHash,metadata.ArtifactHash);Assert.Equal(compiled.Result.SourceHash,metadata.SourceHash);
        using var stream=new MemoryStream(compiled.AssemblyBytes);using var pe=new PEReader(stream);var reader=pe.GetMetadataReader();Assert.Equal(reader.GetGuid(reader.GetModuleDefinition().Mvid),metadata.ModuleId);var method=reader.GetMethodDefinition((MethodDefinitionHandle)MetadataTokens.Handle(metadata.MetadataToken));Assert.Equal("Run",reader.GetString(method.Name));var type=reader.GetTypeDefinition(method.GetDeclaringType());Assert.Equal("Queries",reader.GetString(type.Name));
    }
    [Fact]public void QueryAndExtensionTemplatesDoNotContainLiteralsCommentsOrInterpolationText(){
        var compiled=Compile("var selected=from value in values where value>1234567 select value;/* PRIVATE_COMMENT */return selected.Count()+values.Where(value=>value!=7654321).Select(value=>$\"PRIVATE_LITERAL:{value}\").Where(text=>text!=\"PRIVATE_PASSWORD\").Count();");Assert.NotEmpty(compiled.AssemblyBytes);var metadata=Assert.IsType<Seamless.Management.Server.QueryAuditMetadata>(compiled.AuditMetadata);var template=Assert.IsType<string>(metadata.QueryTemplate);Assert.Contains("from",template);Assert.Contains("Where",template);Assert.Contains("Select",template);Assert.Contains("Count",template);foreach(var secret in new[]{"1234567","7654321","PRIVATE_COMMENT","PRIVATE_LITERAL","PRIVATE_PASSWORD","987654321","DO_NOT_EXECUTE"}){Assert.DoesNotContain(secret,template);}Assert.Contains("@p",template);
    }
    [Fact]public void CodeWithoutQueriesDoesNotBecomeASourceTemplate(){var compiled=Compile("return threshold;");Assert.NotEmpty(compiled.AssemblyBytes);Assert.Null(Assert.IsType<Seamless.Management.Server.QueryAuditMetadata>(compiled.AuditMetadata).QueryTemplate);}
    [Fact]public void LargeTemplatesAreBoundedAndExplicitlyMarked(){var body="var result=0;"+string.Concat(Enumerable.Repeat("result+=values.Where(value=>value>1234567).Sum();",100))+"return result;";var compiled=Compile(body);Assert.NotEmpty(compiled.AssemblyBytes);var text=compiled.AuditMetadata!.QueryTemplate!;Assert.True(text.Length<=8192);Assert.Contains("省略",text);Assert.DoesNotContain("1234567",text);}
    [Fact]public void FailedCompilationDoesNotProduceMethodMetadata(){var compiled=Compile("return missing;");Assert.Empty(compiled.AssemblyBytes);Assert.Null(compiled.AuditMetadata);}
    private static string Root()=>Path.Combine(Environment.GetEnvironmentVariable("SEAMLESS_MANAGEMENT_TEST_ROOT")!,Guid.NewGuid().ToString("N"));
    private static Definition Query()=>new("audit-query","Native",DefinitionKind.Query,"Model.Queries","Run",new("1",[new("Query.cs","using System.Linq;using Seamless.Management.Server;namespace Model;public static class Queries{public static int Run(ManagementExecutionContext context,string token=\"PRIVATE_DEFAULT\")=>context.GetDatabase<Db>().Rows.Where(row=>row.Value>1234567).Select(row=>\"PRIVATE_LITERAL\").Count();}")],[]));
    [Fact]public void PublishedHistoryUsesTheMatchingBuildMetadataAndDoesNotExposeItThroughPlans(){
        var root=Root();string hash;using(var store=ManagementStore.Initialize(root,"admin","TestPassword-123"))using(var service=new Seamless.Management.Server.ManagementService(store)){
            var admin=service.Authenticate(service.Login(new("admin","TestPassword-123")).Token);NativeWorkflow.Publish(service,admin,NativeWorkflow.Database());NativeWorkflow.Publish(service,admin,Query());hash=service.GetDefinition(admin,"audit-query").ArtifactHash;
            var record=Assert.Single(service.AuditEvents(admin,new(Text:"Model.Queries.Run")).Items);Assert.Equal(hash,record.CodeVersion);Assert.Equal("Run",record.MethodName);Assert.Contains("Where",record.QueryTemplate!);foreach(var text in new[]{"PRIVATE_DEFAULT","PRIVATE_LITERAL","1234567","RUNTIME_SECRET"}){Assert.DoesNotContain(text,record.QueryTemplate!);Assert.DoesNotContain(text,record.MethodSignature!);}
            Assert.Equal(0,Assert.Single(service.Execute(admin,new("audit-query",null,ManagementJson.Element(new{token="RUNTIME_SECRET"})),CancellationToken.None)).Value.GetInt32());
            var viewer=new UserAccount("viewer","",[new("Native",ManagementPermission.View)]);Assert.Equal("Permission",Assert.Throws<ManagementException>(()=>service.Plans(viewer,"audit-query")).Code);Assert.DoesNotContain("queryTemplate",System.Text.Json.JsonSerializer.Serialize(service.Plans(admin,"audit-query"),ManagementJson.Options),StringComparison.OrdinalIgnoreCase);
        }
        using var reopened=new ManagementStore(root);var metadata=reopened.Read<Seamless.Management.Server.QueryAuditMetadata>("queryAudit",hash);Assert.NotNull(metadata);Assert.Equal(hash,metadata.ArtifactHash);Assert.Contains(reopened.AuditEvents(new(Text:"Model.Queries.Run")).Items,item=>item.MethodModuleId==metadata.ModuleId&&item.MethodMetadataToken==metadata.MetadataToken);
    }
    [Fact]public void MetadataMismatchBlocksHistoryAndOldArtifactsWithoutMetadataRemainUsable(){
        using var store=ManagementStore.Initialize(Root(),"admin","TestPassword-123");using var service=new Seamless.Management.Server.ManagementService(store);var admin=service.Authenticate(service.Login(new("admin","TestPassword-123")).Token);NativeWorkflow.Publish(service,admin,NativeWorkflow.Database());NativeWorkflow.Publish(service,admin,Query());var hash=service.GetDefinition(admin,"audit-query").ArtifactHash;var metadata=store.Read<Seamless.Management.Server.QueryAuditMetadata>("queryAudit",hash)!;
        store.Write(()=>store.Put("queryAudit",hash,metadata with{SourceHash="mismatch"}));var count=store.AuditEvents(new()).Items.Length;Assert.Throws<InvalidDataException>(()=>store.Write(()=>store.AddHistory("admin","Native","Rebuilt","audit-query",1)));Assert.Equal(count,store.AuditEvents(new()).Items.Length);
        store.Write(()=>store.Put<Seamless.Management.Server.QueryAuditMetadata?>("queryAudit",hash,null));Assert.Equal(0,Assert.Single(service.Execute(admin,new("audit-query",null,ManagementJson.Element(new{token="secret"})),CancellationToken.None)).Value.GetInt32());Assert.Null(store.Read<Seamless.Management.Server.QueryAuditMetadata>("queryAudit",hash));
    }
    [Fact]public void RebuiltQueriesKeepOldAndNewArtifactIdentitiesSeparate(){
        using var store=ManagementStore.Initialize(Root(),"admin","TestPassword-123");using var service=new Seamless.Management.Server.ManagementService(store);var admin=service.Authenticate(service.Login(new("admin","TestPassword-123")).Token);var database=NativeWorkflow.Database();NativeWorkflow.Publish(service,admin,database);NativeWorkflow.Publish(service,admin,Query());var before=service.GetDefinition(admin,"audit-query");var oldMetadata=store.Read<Seamless.Management.Server.QueryAuditMetadata>("queryAudit",before.ArtifactHash)!;
        var expanded=database with{Source=database.Source with{Revision="2",Files=database.Source.Files.Select(file=>file with{Text=file.Text.Replace("public Table<Keys.Row,Tables.Row> Rows=>","public Table<Keys.Row,Tables.Row> Other=>this.Table<Keys.Row,Tables.Row>(row=>new(row.Id));public Table<Keys.Row,Tables.Row> Rows=>",StringComparison.Ordinal)}).ToArray()}};NativeWorkflow.Publish(service,admin,expanded,1,1);
        var after=service.GetDefinition(admin,"audit-query");Assert.Equal(2,after.Version);Assert.NotEqual(before.ArtifactHash,after.ArtifactHash);var current=store.Read<Seamless.Management.Server.QueryAuditMetadata>("queryAudit",after.ArtifactHash)!;Assert.Equal(oldMetadata.SourceHash,current.SourceHash);Assert.NotEqual(oldMetadata.ModuleId,current.ModuleId);Assert.Equal(oldMetadata,store.Read<Seamless.Management.Server.QueryAuditMetadata>("queryAudit",before.ArtifactHash));var events=service.AuditEvents(admin,new(Text:"Model.Queries.Run")).Items;Assert.Contains(events,item=>item.ResultCode=="Applied"&&item.CodeVersion==before.ArtifactHash&&item.MethodModuleId==oldMetadata.ModuleId);Assert.Contains(events,item=>item.ResultCode=="Rebuilt"&&item.CodeVersion==after.ArtifactHash&&item.MethodModuleId==current.ModuleId);
    }
}
